describe('Notification Deletion', () => {
    beforeEach(() => {
        cy.visit('/notifications');
        cy.login(); // Assuming there's a custom command for login
    });

    it('should delete a notification successfully', () => {
        cy.get('.notification-item').first().as('firstNotification');
        cy.get('@firstNotification').find('.delete-button').click();
        cy.get('.confirmation-dialog .confirm-button').click();

        cy.get('@firstNotification').should('not.exist');
        cy.get('.notification-list').should('contain', 'Notification deleted successfully');
    });

    it('should not delete a notification if cancellation is chosen', () => {
        cy.get('.notification-item').first().as('firstNotification');
        cy.get('@firstNotification').find('.delete-button').click();
        cy.get('.confirmation-dialog .cancel-button').click();

        cy.get('@firstNotification').should('exist');
        cy.get('.notification-list').should('not.contain', 'Notification deleted successfully');
    });
});
